<?php declare(strict_types=1); namespace Core\Http\Middleware; use Core\Auth\Auth; use Core\Contracts\MiddlewareInterface; use Core\Exceptions\AuthenticationException; use Core\Exceptions\AuthorizationException; use Core\Http\Request; use Core\Http\Response; use Core\Logging\Log; final class Authorize implements MiddlewareInterface { public function __construct( private readonly Auth $auth, private readonly ?string $parameter = null, ) { } public function handle(Request $request, callable $next): Response { if (!$this->auth->check()) { throw new AuthenticationException(); } if ($this->parameter !== null && !$this->auth->userCan($this->parameter)) { Log::channel('security')->warning('Permission denied', [ 'permission' => $this->parameter, 'user_id' => $this->auth->id(), 'path' => $request->path(), 'ip' => $request->ip(), ]); throw new AuthorizationException(); } return $next($request); } } 